package ru.absurd.carrotcourt.data

/** Saved campaign progress. Decisions remain visible until the player opens the next chapter. */
data class StoryProgress(
    val chapter: Int = 0,
    val seen: Set<String> = emptySet(),
    val decisions: List<Int> = emptyList(),
    val dialogue: Dialogue? = null,
    val completed: Boolean = false,
    val endings: Set<String> = emptySet(),
    val playthroughs: Int = 0
) {
    val decided: Boolean get() = decisions.size > chapter
    val ready: Boolean get() = seen.containsAll(listOf("charge", "defense", "witness"))
    val fairness: Int get() = decisions.count { it == 0 }
}
data class StoryEvidence(val id: String, val speaker: String, val text: String, val clue: String)
data class StoryChoice(val label: String, val consequence: String)
data class StoryChapter(
    val title: String, val location: String, val introduction: String, val consequenceIntro: String,
    val evidence: List<StoryEvidence>, val choices: List<StoryChoice>
)
data class StoryEnding(val id: String, val title: String, val text: String)

