    fun ending(progress: StoryProgress): StoryEnding = when {
        progress.fairness >= 4 && progress.decisions.lastOrNull() == 0 -> endings[0]
        progress.fairness >= 2 -> endings[1]
        else -> endings[2]
    }
}

object StoryEngine {
    fun reveal(state: StoryProgress, evidenceId: String): StoryProgress {
        if (state.completed || state.decided) return state
        val evidence = StoryCatalog.chapters.getOrNull(state.chapter)?.evidence?.find { it.id == evidenceId } ?: return state
        return state.copy(seen = state.seen + evidenceId, dialogue = Dialogue(evidence.speaker, evidence.text))
    }
    fun decide(state: StoryProgress, choice: Int): StoryProgress {
        if (!state.ready || state.decided || state.completed || choice !in 0..1) return state
        val chapter = StoryCatalog.chapters[state.chapter]
        val next = state.copy(decisions = state.decisions + choice,
            dialogue = Dialogue("Решение суда", chapter.choices[choice].consequence))
        return if (state.chapter == StoryCatalog.chapters.lastIndex) next.copy(completed = true,
            endings = next.endings + StoryCatalog.ending(next).id, playthroughs = next.playthroughs + 1) else next
    }
    fun next(state: StoryProgress): StoryProgress = if (state.decided && !state.completed)
        state.copy(chapter = state.chapter + 1, seen = emptySet(), dialogue = null) else state
    fun replay(state: StoryProgress): StoryProgress = if (state.completed)
        StoryProgress(endings = state.endings, playthroughs = state.playthroughs) else state
}
